JOIN (
SELECT YEAR(create_time) AS year,
MONTH(create_time) AS month,
MIN(create_time) AS min_time
FROM ecm_electricity_consumption
WHERE YEAR(create_time) = #{year}
AND electric_device_code = #{electricDeviceCode}
GROUP BY YEAR(create_time), MONTH(create_time)
) e2
ON ecm_electricity_consumption.create_time = e2.min_time
WHERE YEAR(ecm_electricity_consumption.create_time) = #{year}
AND ecm_electricity_consumption.electric_device_code = #{electricDeviceCode}

